"use client";

import { useState } from "react";
import { announcement } from "@/content/site";

/**
 * Thin top banner (Fin G-01). Dismissible for the current visit.
 * From 740px, liquid art sits at both ends like fin.ai's banner: each piece
 * starts at the screen edge, its sharp swirl edge faces the text, and it is
 * cropped from the outside as the screen narrows. Below 740px it is hidden.
 * The art is generated by scripts/liquid-banner/render.mjs.
 */
export function AnnouncementBar() {
  const [open, setOpen] = useState(true);
  if (!open) return null;

  return (
    <div data-announcement className="relative flex min-h-[34px] items-stretch bg-banner text-xs/snug text-off-black sm:text-sm/5">
      <div aria-hidden className="hidden min-w-0 flex-1 min-[740px]:block">
        <div className="h-full max-w-[500px] bg-[url(/art/banner-liquid-left.webp)] bg-[length:auto_100%] bg-right bg-no-repeat" />
      </div>
      <a
        href={announcement.href}
        className="group flex min-w-0 flex-1 items-center justify-center gap-2 px-10 py-2 text-center min-[740px]:flex-none min-[740px]:whitespace-nowrap min-[740px]:px-4 min-[740px]:py-[7px]"
      >
        <span className="underline decoration-ink/30 underline-offset-[3px] group-hover:decoration-ink">
          {announcement.text}
        </span>
        <svg aria-hidden viewBox="0 0 16 16" className="size-3.5 shrink-0" fill="none" stroke="currentColor" strokeWidth="1.5">
          <path d="M3 8h10M9 4l4 4-4 4" />
        </svg>
      </a>
      <div aria-hidden className="hidden min-w-0 flex-1 justify-end min-[740px]:flex">
        <div className="h-full w-full max-w-[600px] bg-[url(/art/banner-liquid-right.webp)] bg-[length:auto_100%] bg-left bg-no-repeat" />
      </div>
      <button
        type="button"
        aria-label="Close"
        onClick={() => setOpen(false)}
        className="absolute right-[calc(var(--frame)-8px)] top-1/2 grid size-7 -translate-y-1/2 place-items-center text-off-black transition-opacity hover:opacity-70 min-[740px]:text-white"
      >
        <svg aria-hidden viewBox="0 0 16 16" className="size-3" fill="none" stroke="currentColor" strokeWidth="1.5">
          <path d="M3 3l10 10M13 3L3 13" />
        </svg>
      </button>
    </div>
  );
}
